}

/* 头像区底部分割线 */
.mes_block::after {
    content: '' !important;
    display: block !important;
    position: absolute !important;
    top: 70px !important;
    left: 0 !important;
    width: 100% !important;
    height: 0.5px !important;
    background-color: #B8B3B5 !important;
    pointer-events: none !important;
}


/* 用户消息描边改粉色 */
.mes[is_user="true"] .mes_block {
    border: 0.5px solid #949292 !important;
}

/* 用户消息分割线改粉色，单独覆盖 */
.mes[is_user="true"] .mes_block::after {
    background-color: #B8B3B5 !important;
}

